[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Lichess Chess Game Analytics: Patterns of Victory, Openings, and Player Dynamics</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface-alt: #22262f;
    --border: #2d3140;
    --text: #e1e4e8;
    --text-secondary: #8b949e;
    --accent: #58a6ff;
    --accent-green: #3fb950;
    --accent-red: #f85149;
    --accent-yellow: #d29922;
    --accent-purple: #a371f7;
    --white-color: #f0f6fc;
    --black-color: #8b949e;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
  }
  .container { max-width: 1100px; margin: 0 auto; padding: 0 24px; }
  header {
    background: linear-gradient(135deg, #1a1d27 0%, #1f2937 100%);
    border-bottom: 2px solid var(--accent);
    padding: 60px 0 40px;
    text-align: center;
  }
  header h1 {
    font-size: 2.2em;
    color: #fff;
    margin-bottom: 10px;
    letter-spacing: -0.5px;
  }
  header .subtitle { color: var(--text-secondary); font-size: 1.1em; max-width: 700px; margin: 0 auto; }
  .meta-bar {
    display: flex; justify-content: center; gap: 40px; margin-top: 24px;
    font-size: 0.9em; color: var(--text-secondary);
  }
  .meta-bar span { display: flex; align-items: center; gap: 6px; }
  .meta-bar .val { color: var(--text); font-weight: 600; }
  .kpi-row {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px; margin: 40px 0;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px;
    text-align: center;
  }
  .kpi-card .label { font-size: 0.8em; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; }
  .kpi-card .value { font-size: 2em; font-weight: 700; color: var(--accent); margin: 6px 0; }
  .kpi-card .note { font-size: 0.8em; color: var(--text-secondary); }
  section { margin: 48px 0; }
  section h2 {
    font-size: 1.6em;
    color: #fff;
    border-bottom: 2px solid var(--border);
    padding-bottom: 10px;
    margin-bottom: 20px;
  }
  section h3 { font-size: 1.2em; color: var(--text); margin: 28px 0 12px; }
  .chart-box {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px;
    margin: 20px 0;
  }
  .chart-box h4 { font-size: 1em; color: var(--text-secondary); margin-bottom: 16px; font-weight: 500; }
  .chart-box canvas { max-height: 380px; }
  .chart-row {
    display: grid; grid-template-columns: 1fr 1fr;
    gap: 20px; margin: 20px 0;
  }
  @media (max-width: 768px) { .chart-row { grid-template-columns: 1fr; } }
  .stats-table {
    width: 100%; border-collapse: collapse; margin: 16px 0;
    font-size: 0.9em;
  }
  .stats-table th {
    background: var(--surface-alt);
    color: var(--text-secondary);
    text-transform: uppercase;
    font-size: 0.75em;
    letter-spacing: 0.5px;
    padding: 10px 14px;
    text-align: left;
    border-bottom: 2px solid var(--border);
  }
  .stats-table td {
    padding: 9px 14px;
    border-bottom: 1px solid var(--border);
  }
  .stats-table tr:hover td { background: rgba(88,166,255,0.04); }
  .highlight-number { font-weight: 700; color: var(--accent); }
  .positive { color: var(--accent-green); }
  .negative { color: var(--accent-red); }
  .callout {
    background: var(--surface);
    border-left: 3px solid var(--accent);
    padding: 16px 20px;
    margin: 20px 0;
    border-radius: 0 8px 8px 0;
    font-size: 0.95em;
  }
  .callout.warning { border-left-color: var(--accent-yellow); }
  .callout.green { border-left-color: var(--accent-green); }
  .text-block { font-size: 0.95em; color: var(--text); margin: 12px 0; }
  .text-block strong { color: #fff; }
  footer {
    border-top: 1px solid var(--border);
    padding: 32px 0;
    text-align: center;
    color: var(--text-secondary);
    font-size: 0.85em;
  }
  .key-finding {
    display: flex; gap: 16px; margin: 16px 0;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 16px 20px;
  }
  .key-finding .num {
    background: var(--accent);
    color: #000;
    border-radius: 50%;
    width: 28px; height: 28px;
    display: flex; align-items: center; justify-content: center;
    font-weight: 700; font-size: 0.85em;
    flex-shrink: 0;
  }
  .toc { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 24px 28px; margin: 40px 0; }
  .toc h3 { margin-top: 0; color: var(--text-secondary); text-transform: uppercase; font-size: 0.8em; letter-spacing: 0.5px; }
  .toc ol { margin: 12px 0 0 20px; }
  .toc li { margin: 6px 0; }
  .toc a { color: var(--accent); text-decoration: none; }
  .toc a:hover { text-decoration: underline; }
