    <tbody>
      <tr><td>Bullet (&lt;3 min)</td><td>5,097</td><td>51.1%</td><td>3.7%</td><td>57.4</td><td class="highlight-number">14.0%</td><td>41.1%</td><td>41.1%</td></tr>
      <tr><td>Blitz (3&ndash;10 min)</td><td>10,957</td><td>51.8%</td><td>4.4%</td><td>61.0</td><td>7.6%</td><td>31.9%</td><td>56.1%</td></tr>
